package net.civeira.phylax.features.access.usergroupmembership.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class RolesVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property roles of user group membership ")
  void test_roles_v_o_builder() {
    Assertions.assertFalse(RolesVO.nullValue().getRoles().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(RolesVO.tryFrom(null).getRoles().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", RolesVO.from("one").getRoles().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> RolesVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", RolesVO.from("one").toString());
  }
}
